def classify_album_cover(genre, theme):
    genres = {'rock': ['Genesis', 'Rolling Stones'], 'pop': ['Taylor Swift', 'Justin Bieber']}
    themes = {'people_with_heads': True, 'people_on_floats': False}
    if (theme in themes and themes[theme]) or (genre in genres and 'Genesis' in genres[genre]):
        return 'good'
    else:
        return 'bad'

